<script setup>
import {ref,computed,watch,onUnmounted} from 'vue';import {framesFor} from '../visuals';
const props=defineProps({type:String});const frames=computed(()=>framesFor(props.type)),at=ref(0),speed=ref(1600),playing=ref(false);let timer;
const f=computed(()=>frames.value[at.value]);watch(()=>props.type,()=>{stop();at.value=0});
function stop(){clearInterval(timer);playing.value=false;}function play(){if(playing.value){stop();return}if(at.value===frames.value.length-1)at.value=0;playing.value=true;timer=setInterval(()=>{if(at.value<frames.value.length-1)at.value++;else stop()},Number(speed.value));}
function next(d){stop();at.value=Math.max(0,Math.min(frames.value.length-1,at.value+d));}watch(speed,()=>{if(playing.value){stop();play()}});onUnmounted(stop);
const treePos=computed(()=>f.value.shape==='heap'?[[260,30],[140,105],[380,105],[80,180],[200,180],[320,180]]:[[260,30],[140,105],[380,105],[320,180],[440,180]]);
const treeEdges=computed(()=>f.value.shape==='heap'?[[0,1],[0,2],[1,3],[1,4],...(f.value.values.length>5?[[2,5]]:[])]:[[0,1],[0,2],[2,3],[2,4]]);
const graphPos=[[70,100],[230,35],[230,175],[420,100]];
const edges=computed(()=>f.value.weighted?[[0,1,1],[0,2,4],[1,2,2],[1,3,5],[2,3,1]]:[[0,1],[0,2],[1,3],[2,3]]);
</script>
<template><section class="visualizer"><div class="section-bar"><h3>图解实验台</h3><span class="micro">{{at+1}} / {{frames.length}}</span></div><div class="visual-stage">
<svg v-if="f.kind==='tree'" viewBox="0 0 520 220" class="node-svg" role="img" :aria-label="f.text"><line v-for="(edge,i) in treeEdges" :key="'l'+i" :x1="treePos[edge[0]][0]" :y1="treePos[edge[0]][1]" :x2="treePos[edge[1]][0]" :y2="treePos[edge[1]][1]"/><g v-for="(v,i) in f.values" :key="i" :class="{lit:f.active.includes(i)}"><rect :x="treePos[i][0]-22" :y="treePos[i][1]-20" width="44" height="40"/><text :x="treePos[i][0]" :y="treePos[i][1]+6">{{v}}</text></g></svg>
<svg v-else-if="f.kind==='graph'" viewBox="0 0 500 220" class="node-svg" role="img" :aria-label="f.text"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="16" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="currentColor"/></marker></defs><g v-for="(e,i) in edges" :key="i"><line :x1="graphPos[e[0]][0]" :y1="graphPos[e[0]][1]" :x2="graphPos[e[1]][0]" :y2="graphPos[e[1]][1]" :marker-end="f.weighted?'url(#arrow)':null"/><text v-if="f.weighted" class="edge-label" :x="(graphPos[e[0]][0]+graphPos[e[1]][0])/2+10" :y="(graphPos[e[0]][1]+graphPos[e[1]][1])/2-6">{{e[2]}}</text></g><g v-for="(v,i) in f.values" :key="i" :class="{lit:f.active.includes(i)}"><rect :x="graphPos[i][0]-20" :y="graphPos[i][1]-20" width="40" height="40"/><text :x="graphPos[i][0]" :y="graphPos[i][1]+6">{{v}}</text></g></svg>
<div v-else class="tiles" :class="[f.kind||'array',{grid:f.kind==='grid',stack:f.kind==='stack'}]"><template v-for="(v,i) in f.values" :key="i"><div class="tile-wrap"><div class="tile" :class="{active:f.active.includes(i),faded:f.range&&(i<f.range[0]||i>f.range[1]),colored:f.kind==='grid'&&v===2}">{{v}}</div><small v-if="!f.kind||f.kind==='linked'">{{f.labels?.[i]??i}}</small></div><span v-if="f.kind==='linked'&&i<f.values.length-1" class="connector">→</span></template></div>
<div v-if="f.secondary" class="secondary"><small>{{f.label}}</small><div class="tiles"><div v-for="(v,i) in f.secondary" class="tile small-tile" :key="i">{{v}}</div></div></div><p class="visual-message" aria-live="polite">{{f.text}}</p></div>
<div class="visual-controls"><button @click="next(-1)" :disabled="at===0">← 上一步</button><button class="primary" @click="play">{{playing?'Ⅱ 暂停':'▶ 播放'}}</button><button @click="next(1)" :disabled="at===frames.length-1">下一步 →</button><button @click="stop();at=0">重来</button><select v-model="speed" aria-label="演示速度"><option :value="3200">0.5×</option><option :value="1600">1×</option><option :value="800">2×</option></select></div><label class="timeline"><span>步骤</span><input type="range" min="0" :max="frames.length-1" v-model.number="at" @input="stop" aria-label="图解步骤"/></label><p class="micro legend">深色＝当前关注的位置；数字下方是编号。这里演示概念步骤，Java 的语句含义见下方逐行说明。</p></section></template>
